      set('[data-exchange-search]',exchangeState.search);set('[data-exchange-sort]',exchangeState.sort);set('[data-exchange-urgency]',exchangeState.urgency);set('[data-exchange-distance]',exchangeState.distanceMax);set('[data-exchange-price-min]',exchangeState.priceMin||'');set('[data-exchange-price-max]',exchangeState.priceMax||'');
