      page.querySelectorAll('[data-exchange-urgency-value]').forEach(x=>x.classList.toggle('is-active',String(x.dataset.exchangeUrgencyValue||'all')===String(exchangeState.urgency||'all')));
      page.querySelectorAll('[data-exchange-sort-value]').forEach(x=>x.classList.toggle('is-active',String(x.dataset.exchangeSortValue||'recommended')===String(exchangeState.sort||'recommended')));
